/**
 * @component button-set
 * @summary A seamed (flush, zero-gap) row of buttons, with only its outer two corners rounded.
 * @remarks Its own chained modifiers (`-color-*`, `-size-*`, `-shape-*`, `-toggle`, `-condensed`,
 *   `-without-background`, `-without-border`, `-display-block`) set a default for every child
 *   `.pfx-button` that doesn't carry its own modifier in that same category — a button's own
 *   modifier class always wins over the group's default. `-icon-*` is always per-button; it's
 *   never read from the group. Deprecated button aliases (`-ghost`, `-color-primary-inverse`)
 *   aren't supported as group-level modifiers — use their canonical replacements
 *   (`-color-tertiary`, `-on-color`) instead.
 * @modifier -color-primary — Default every unmodified child to the primary color.
 * @modifier -color-secondary — Default every unmodified child to the secondary color.
 * @modifier -color-tertiary — Default every unmodified child to the tertiary (text-style) color.
 * @modifier -color-danger — Default every unmodified child to the destructive color.
 * @modifier -color-success — Default every unmodified child to the success color.
 * @modifier -color-ai — Default every unmodified child to the AI gradient treatment.
 * @modifier -color-ai-secondary — Default every unmodified child to the lower-emphasis AI treatment.
 * @modifier -on-color — Default every unmodified child for placement on a coloured surface.
 * @modifier -size-sm — Default every unmodified child to small.
 * @modifier -size-md — (default) medium size.
 * @modifier -size-lg — Default every unmodified child to large.
 * @modifier -shape-circle — Default every unmodified child to a round icon button.
 * @modifier -shape-square — Default every unmodified child to a square icon button.
 * @modifier -toggle — Default every unmodified child to the pressed-state toggle treatment.
 * @modifier -condensed — Default every unmodified child to tighter padding.
 * @modifier -without-background — Default every unmodified child to no fill.
 * @modifier -without-border — Default every unmodified child to no border.
 * @modifier -display-block — Lay every unmodified child out full-width.
 * @structure
 * .pfx-button-set {
 *   @component button:one-or-more {}
 * }
 * @example
 * ```html
 * <div class="pfx-button-set -size-sm -toggle">
 *   <button class="pfx-button">Left</button>
 *   <button class="pfx-button">Right</button>
 * </div>
 * ```
 * ### Per-button override
 * ```html
 * <div class="pfx-button-set -color-secondary">
 *   <button class="pfx-button -icon-x">Cancel</button>
 *   <button class="pfx-button -color-primary -icon-checkmark">Confirm</button>
 * </div>
 * ```
 * @related button — The child control this wraps.
 */
.pfx-button-set {
  display: flex;
  align-items: center;
  flex-wrap: wrap;
  gap: 0;
}

.pfx-button-set > .pfx-button {
  border-radius: 0;
}

/* Collapses the doubled border at each seam to a single line. */
.pfx-button-set > .pfx-button:not(:first-child) {
  border-inline-start: 0;
}

