  border-start-start-radius: var(--instui-component-base-button-border-radius);
  border-end-start-radius: var(--instui-component-base-button-border-radius);
}

.pfx-button-set > .pfx-button:last-child {
  border-start-end-radius: var(--instui-component-base-button-border-radius);
  border-end-end-radius: var(--instui-component-base-button-border-radius);
