  background: var(--instui-component-base-button-primary-disabled-background-color);
  border-color: var(--instui-component-base-button-primary-disabled-border-color);
  color: var(--instui-component-base-button-primary-color);
}

.pfx-button-set.-color-secondary > .pfx-button:not([class*="-color-"]) {
  background: var(--instui-component-base-button-secondary-background);
  color: var(--instui-component-base-button-secondary-color);
